<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Notes Studio</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
    <style>
        :root{--bg:#0f172a;--card:#111827;--muted:#1e293b;--line:#334155;--text:#f8fafc;--sub:#cbd5e1;--teal:#0d9488;--orange:#ea580c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif}button,input,textarea{font:inherit}button{cursor:pointer}.shell{display:grid;grid-template-columns:240px 1fr;min-height:100vh}.side{padding:30px 20px;border-right:1px solid var(--line);background:#0b1220}.brand{display:flex;align-items:center;gap:10px;font-weight:700;font-size:17px;margin-bottom:52px}.mark{width:30px;height:30px;background:var(--teal);display:grid;place-items:center;border-radius:8px;color:#061c1b;font-weight:700}.nav{display:grid;gap:8px}.nav a{color:var(--sub);text-decoration:none;padding:11px 13px;border-radius:8px}.nav a.active,.nav a:hover{background:var(--muted);color:var(--text)}.side-note{position:absolute;bottom:28px;color:#64748b;font-size:12px;line-height:1.6}.main{max-width:1180px;width:100%;padding:42px 6vw}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:34px}.eyebrow{color:#5eead4;font-size:12px;font-weight:600;letter-spacing:.1em;text-transform:uppercase}.top h1{font-size:34px;letter-spacing:-.04em;margin:8px 0}.top p{color:var(--sub);margin:0}.new{border:0;background:var(--orange);color:white;border-radius:7px;padding:12px 17px;font-weight:600;transition:transform .2s,background .2s}.new:hover{background:#f97316;transform:translateY(-2px)}.tools{display:flex;gap:10px;margin-bottom:26px}.search{flex:1;position:relative}.search input{width:100%;background:var(--card);border:1px solid var(--line);border-radius:7px;padding:12px 14px;color:var(--text);outline:none}.search input:focus{border-color:var(--teal);box-shadow:0 0 0 3px #0d948833}.filter{background:var(--card);border:1px solid var(--line);color:var(--sub);border-radius:7px;padding:0 15px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(245px,1fr));gap:16px}.note{background:var(--card);border:1px solid var(--line);border-top:3px solid var(--teal);border-radius:8px;padding:20px;min-height:180px;display:flex;flex-direction:column;animation:rise .45s both;transition:transform .2s,border-color .2s}.note:nth-child(2){animation-delay:.06s}.note:nth-child(3){animation-delay:.12s}.note:nth-child(4){animation-delay:.18s}.note:hover{transform:translateY(-4px);border-color:#64748b}.note.orange{border-top-color:var(--orange)}.note.violet{border-top-color:#8b5cf6}.note h2{font-size:17px;margin:0 0 10px}.note p{color:var(--sub);line-height:1.65;margin:0;white-space:pre-line;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden}.meta{margin-top:auto;padding-top:18px;color:#64748b;font-size:11px;display:flex;justify-content:space-between}.actions{display:flex;gap:12px}.icon{background:none;border:0;color:#64748b;padding:0;font-size:12px}.icon:hover{color:var(--text)}.empty{grid-column:1/-1;border:1px dashed var(--line);padding:60px;text-align:center;color:var(--sub)}.modal{display:none;position:fixed;inset:0;background:#020617aa;place-items:center;padding:20px}.modal.show{display:grid}.dialog{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:25px;width:min(520px,100%)}.dialog h2{margin:0 0 20px}.dialog input,.dialog textarea{display:block;width:100%;background:#0b1220;border:1px solid var(--line);color:var(--text);border-radius:6px;padding:12px;margin:8px 0 14px;outline:none}.dialog textarea{min-height:150px;resize:vertical}.dialog input:focus,.dialog textarea:focus{border-color:var(--teal)}.dialog-actions{display:flex;justify-content:flex-end;gap:10px}.cancel{background:none;border:1px solid var(--line);color:var(--sub);padding:10px 15px;border-radius:6px}.save{background:var(--teal);border:0;color:#021c1b;font-weight:600;padding:10px 15px;border-radius:6px}@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}@media(max-width:700px){.shell{display:block}.side{border-right:0;border-bottom:1px solid var(--line);padding:18px 20px}.brand{margin:0}.nav,.side-note{display:none}.main{padding:30px 20px}.top h1{font-size:28px}.top{align-items:flex-end}.new{padding:10px 12px}.filter{display:none}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important}}
    </style>
</head>
<body>
<div class="shell">
    <aside class="side"><div class="brand"><span class="mark">N</span> Notes Studio</div><nav class="nav"><a class="active" href="{{ route('notes.index') }}">All notes</a><a href="{{ route('notes.index') }}?search=important">Important</a></nav><div class="side-note">A quieter place for<br>loud ideas.</div></aside>
    <main class="main">
        <header class="top"><div><div class="eyebrow">Personal workspace</div><h1>All notes</h1><p>{{ $notes->count() }} {{ Str::plural('note', $notes->count()) }} in your collection</p></div><button class="new" onclick="openModal()">+ New note</button></header>
        <form class="tools" method="GET"><div class="search"><input name="search" value="{{ $search ?? '' }}" placeholder="Search your notes..." aria-label="Search notes"></div><button class="filter" type="submit">Search</button></form>
        <section class="grid">@forelse($notes as $note)<article class="note {{ $note->color }}"><h2>{{ $note->title }}</h2><p>{{ $note->content }}</p><div class="meta"><span>{{ $note->updated_at->diffForHumans() }}</span><span class="actions"><form method="POST" action="{{ route('notes.destroy',$note) }}">@csrf @method('DELETE')<button class="icon" aria-label="Delete note">Delete</button></form></span></div></article>@empty<div class="empty">No notes yet. Start with one clear thought.</div>@endforelse</section>
    </main>
</div>
<div class="modal" id="modal" onclick="if(event.target===this)closeModal()"><form class="dialog" method="POST" action="{{ route('notes.store') }}">@csrf<h2>New note</h2><label>Title<input name="title" required maxlength="120" autofocus></label><label>Content<textarea name="content" placeholder="Capture the thought..."></textarea></label><label>Color<select name="color"><option value="teal">Teal</option><option value="orange">Orange</option><option value="violet">Violet</option></select></label><div class="dialog-actions"><button type="button" class="cancel" onclick="closeModal()">Cancel</button><button class="save">Save note</button></div></form></div>
<script>const modal=document.getElementById('modal');function openModal(){modal.classList.add('show');modal.querySelector('input').focus()}function closeModal(){modal.classList.remove('show')}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()})</script>
</body>
</html>
